import {assert,equal,info,digest,candidate,records,append,FILE,LIST,SHA,OLD_SHA} from './core.mjs';
export class Installer{
  constructor(fs,identify,log=()=>{}){this.fs=fs;this.identify=identify;this.log=log;this.state='new';this.saved=false;this.backup=new Map();}
  invalidate(){this.state='disconnected';this.saved=false;}
  async inspect(data){assert(this.state==='new','Reconecte para iniciar uma nova leitura.');this.state='reading';try{await candidate(data);this.data=data.slice();await this.identify();this.files=await this.fs.list();assert(this.files.some(f=>f.name===LIST),'FLST_SEQ.ZDT não encontrado com o nome esperado.');assert(this.files.reduce((n,f)=>n+f.size,0)<=4*1024*1024,'Backup excede o limite suportado.');for(let n=0;n<this.files.length;n++){const f=this.files[n];this.log(`Lendo ${n+1}/${this.files.length}: ${f.name}`);const b=await this.fs.read(f.name,f.size);this.backup.set(f.name,b);assert(this.state!=='disconnected','USB desconectado.');}this.plan=await this.check(this.backup);this.free=await this.fs.free();assert(this.plan.mode==='current'||this.free>=32768,'São necessários pelo menos 32 KiB livres para esta operação.');this.state=this.plan.mode==='current'?'current':'ready';return this.plan;}catch(e){this.state='blocked';throw e;}}
  async check(files){const list=files.get(LIST);assert(list,'Backup da lista ausente.');const {rows}=records(list);let ours=null;const ids=new Map();for(const [name,data] of files){if(!name.toUpperCase().endsWith('.ZDL')||name.toUpperCase()==='CMN_DRV.ZDL')continue;const h=info(data);assert(!ids.has(h.gid+':'+h.id),`IDs duplicados: ${name} e ${ids.get(h.gid+':'+h.id)}.`);ids.set(h.gid+':'+h.id,name);if(h.id===958){assert(name===FILE&&h.gid===8,`O ID 958 já pertence a ${name}. A instalação foi bloqueada.`);}if(name.toUpperCase()===FILE){assert(name===FILE&&h.gid===8&&h.id===958,'O nome FLTDLBS.ZDL está ocupado por outro efeito.');const hash=await digest(data);assert(hash===SHA||hash===OLD_SHA,'A versão existente de FLTDLBS.ZDL é desconhecida.');ours={hash,data};}}
    for(const r of rows)assert(files.has(r.name),`O arquivo listado ${r.name} está ausente. Lista inconsistente.`);
    const matches=rows.filter(r=>r.name.toUpperCase()===FILE);if(ours){assert(matches.length===1&&matches[0].gid===8,'A versão existente não está corretamente registrada na categoria Delay.');return {mode:ours.hash===SHA?'current':'update',list,previous:ours.data};}
    assert(matches.length===0,'A lista já cita FLTDLBS.ZDL, mas o arquivo não existe.');return {mode:'add',list,next:append(list)};
  }
  acknowledgeBackup(){assert(this.state==='ready','Backup ainda indisponível.');this.saved=true;}
  async install(){assert(this.state==='ready'&&this.saved,'Salve e confirme o backup antes de instalar.');this.state='checking';let writing=false,listTouched=false;try{await this.identify();const fresh=await this.fs.list();assert(JSON.stringify(fresh)===JSON.stringify(this.files),'O diretório mudou. Reconecte e faça um novo backup.');const heads=new Map();for(const f of fresh){if(f.name===LIST)heads.set(f.name,await this.fs.read(f.name,f.size));else if(f.name.toUpperCase().endsWith('.ZDL')){const b=await this.fs.read(f.name,f.size,true);const old=this.backup.get(f.name);assert(equal(b,old.slice(0,b.length)),'O efeito '+f.name+' mudou desde o backup.');heads.set(f.name,b);}}
    assert(equal(heads.get(LIST),this.plan.list),'A lista mudou desde o backup.');if(this.plan.previous)assert(equal(await this.fs.read(FILE,this.plan.previous.length),this.plan.previous),'A versão existente mudou.');assert(await this.fs.free()>=32768,'Espaço livre insuficiente.');await candidate(this.data);this.state='writing';writing=true;await this.fs.write(FILE,this.data);if(this.plan.mode==='add'){listTouched=true;await this.fs.write(LIST,this.plan.next);}this.state='done';this.log('Gravação e leitura de retorno concluídas. O áudio e o LCD ainda precisam de teste físico.');return true;
    }catch(e){if(!writing){if(this.state!=='disconnected')this.state='blocked';throw e;}this.state='recovering';try{if(listTouched)await this.fs.write(LIST,this.plan.list);if(this.plan.previous)await this.fs.write(FILE,this.plan.previous);this.state='failed';throw new Error(e.message+' A lista/versão anterior foi preservada ou restaurada e conferida. Se a adição falhou, FLTDLBS.ZDL pode ter ficado sem registro; guarde o backup.');}catch(recovery){if(this.state==='failed')throw recovery;this.state='recovery-required';throw new Error(e.message+' A recuperação também falhou: '+recovery.message+' Não reinicie a pedaleira antes de restaurar os arquivos pelo backup.');}}
  }
}
